 return f'<li class="evidence"><a href="{H(e["url"])}" target="_blank" rel="noopener"><img src="{H(thumb(e))}" loading="lazy" width="160" height="90" alt="Source thumbnail for {H(e["title"])}"></a><div><a href="{H(e["url"])}" target="_blank" rel="noopener">{H(e["title"])}</a><p>{H(e["channel"])} · <b>{f"{score:.2f}×" if score is not None else "Unscored"}</b> · {status}</p><small>{fmt(view)+" source views · " if view else ""}{H(e.get("published",""))}<br>{H(e["basis"])}<br>{H(e.get('relevance','Original reference set.'))}</small></div></li>'
